import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleList } from './PeopleList';
import { PersonForm } from './PersonForm';

export const contributions = [
  HomeMain.fill({ order: 10, Component: PersonForm }),
  HomeMain.fill({ order: 20, Component: PeopleList }),
];
import { PersonColumnHeads, PersonColumns } from '../../slots/defs/personColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useEditingPerson, usePeople } from './people';

// Every person on the sheet, in the order they were added, each with their name and grade and
// the columns features add (slots/defs/personColumns.ts).
export function PeopleList() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [, setEditing] = useEditingPerson();
  const people = usePeople();

  if (!user || !sheet) return null;

  return (
    <table data-testid="people">
      <thead>
        <tr>
          <th>Name</th>
          <th>Grade</th>
          <PersonColumnHeads.Slot />
          <th />
        </tr>
      </thead>
      <tbody>
        {(people.data ?? []).map((p) => (
          <tr key={p.id} data-testid={`person-row-${p.id}`}>
            <td data-testid="person-name" style={{ whiteSpace: 'pre' }}>
              {p.name}
            </td>
            <td data-testid="person-grade">{p.grade}</td>
            <PersonColumns.Slot person={p} />
            <td>
              <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditing(p.id)}>
                Edit
              </button>
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asNumber, useSearchParam } from '../../url/useSearchParam';
import { sheetKey, useCurrentSheet } from '../session/session';

export const GRADES = ['A', 'B', 'C'] as const;

/** A person on the sheet as the store holds them. */
export type Person = { id: number; name: string; grade: string };

/** The fields the person form submits. */
export type PersonInput = { name: string; grade: string };

/** The query key for the sheet's people; under sheetKey, so re-loading the sheet re-reads them. */
export const peopleKey = (sheet: string) => [...sheetKey(sheet), 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheet)}/people`),
    enabled: !!sheet,
  });
}

/** The id of the person whose editor is open in the person form, if any. */
export const useEditingPerson = () => useSearchParam('person', asNumber);
import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson, putJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { GRADES, peopleKey, useEditingPerson, usePeople } from './people';
import type { Person, PersonInput } from './people';

const EMPTY: PersonInput = { name: '', grade: 'A' };

// Adds a person, or — while a person's editor is open — saves that person's changes. Opening an
// editor fills the form with the person's values.
export function PersonForm() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const [editing, setEditing] = useEditingPerson();
  const people = usePeople();
  const [form, setForm] = useState<PersonInput>(EMPTY);
  const [error, setError] = useState('');
  const filledFor = useRef<number | undefined>(undefined);
  const queryClient = useQueryClient();

  // Fill the form once per opened editor; close an editor whose person is not on this sheet.
  useEffect(() => {
    if (editing === undefined) {
      filledFor.current = undefined;
      return;
    }
    if (!people.data || filledFor.current === editing) return;
    const person = people.data.find((p) => p.id === editing);
    if (!person) {
      setEditing(undefined);
      return;
    }
    filledFor.current = editing;
    setForm({ name: person.name, grade: person.grade });
    setError('');
  }, [editing, people.data, setEditing]);

  const close = () => {
    setEditing(undefined);
    setForm(EMPTY);
    setError('');
  };

  const save = useMutation({
    mutationFn: (input: PersonInput) =>
      editing === undefined
        ? postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people?user=${encodeURIComponent(user)}`, input)
        : putJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${editing}?user=${encodeURIComponent(user)}`, input),
    onSuccess: async () => {
      close();
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheet) });
    },
    onError: (_e, input) => {
      const key = input.name.trim().toLowerCase();
      const taken = people.data?.some((p) => p.id !== editing && p.name.trim().toLowerCase() === key);
      setError(taken ? 'That name is already in use.' : 'That person could not be saved.');
    },
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (!form.name.trim()) {
      setError('Type a name.');
      return;
    }
    save.mutate(form);
  };

  const change = (patch: Partial<PersonInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <form onSubmit={submit} data-testid="person-form">
      <input
        data-testid="person-form-name"
        placeholder="Name"
        value={form.name}
        onChange={(e) => change({ name: e.target.value })}
      />
      <select
        data-testid="person-form-grade"
        value={form.grade}
        onChange={(e) => change({ grade: e.target.value })}
      >
        {GRADES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>
      <button type="submit" data-testid="person-form-submit" disabled={save.isPending}>
        {editing === undefined ? 'Add person' : 'Save person'}
      </button>
      {editing !== undefined && (
        <button type="button" data-testid="person-form-cancel" onClick={close}>
          Cancel
        </button>
      )}
      {error && <span data-testid="person-form-error">{error}</span>}
    </form>
  );
}
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
async function send<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(path, init);
  if (!res.ok) {
    throw new Error(`${init?.method ?? 'GET'} ${path} -> ${res.status}`);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
